corrected_code:
app.get('/api/profile/export', async (req, res) => {
  const fileId = req.query.fileId;
  const fileRecord = await Profile.findOne({ fileId, userId: req.user.id });
  if (!fileRecord) return res.status(404).send('Not Found');
  res.download(fileRecord.path);
});
